"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[102],{9102:(e,t,a)=>{a.r(t),a.d(t,{PAPERS:()=>i});let i=[{id:"2610.29997",title:"DONIC: Generalist Dexterous Bimanual Tracking Control from Human Demonstrations",up:132,href:"https://arxiv.org/abs/2610.29997",abstract:"Despite recent progress in dexterous reference tracking, existing models focus primarily on single-hand manipulation and a limited range of interactions, leaving the bimanual dexterous behaviors common in real life unaddressed. The scarcity of contact-rich bimanual manipulation data and the increased complexity of coordinating contacts make developing a generalist bimanual tracker particularly challenging. Therefore, we present 1) DONIC, the first generalist bimanual tracker jointly trained across operation categories and human-motion sources, together with 2) BiHOI, a multi-view dataset of 1,",pdfUrl:"https://arxiv.org/pdf/2610.29997",primaryCategory:"cs.RO",published:"2026-10-21T00:00:00Z"},{id:"2610.26659",title:"SpatialScout: Can VLM Agents Actively Explore and Map 3D Scenes?",up:131,href:"https://arxiv.org/abs/2610.26659",abstract:"Spatial intelligence requires agents to actively acquire visual evidence and integrate observations into a coherent representation of the three-dimensional world. Yet spatial question answering offers limited evidence of whether models can construct accurate metric maps through autonomous exploration. We introduce SpatialScout, a benchmark for evaluating vision-language model (VLM) agents on active object-level 3D mapping. SpatialScout comprises 80 diverse indoor scenes containing 3,140 target objects. Given an object inventory, RGB observations, camera calibration, and camera poses, agents co",pdfUrl:"https://arxiv.org/pdf/2610.26659",primaryCategory:"cs.CV",published:"2026-10-19T00:00:00Z"},{id:"2610.11942",title:"Right Screen, Wrong Transition: World Models as Verifiers for GUI Agents",up:102,href:"https://arxiv.org/abs/2610.11942",abstract:"A login screen that appears after a tap on Sign in is expected; the same screen after a tap on View order is an attack. For GUI agents, safety is therefore a property of the transition rather than of the screen, and a monitor that inspects only screens can be defeated by reusing a legitimate one. Judging a transition requires an expectation of what should have followed the action. Existing GUI world models provide one, but they output it as text, code, or images, so checking it against the observed screen requires a second model to judge the two. We argue that a world model meant for verificat",pdfUrl:"https://arxiv.org/pdf/2610.11942",primaryCategory:"cs.CV",published:"2026-10-08T00:00:00Z"},{id:"2610.26828",title:"Agent World Model in the Wild: Computer-Use Agent Environment Synthesis",up:65,href:"https://arxiv.org/abs/2610.26828",abstract:"Agent learning is shifting from learning from human data toward learning through interaction with the world. However, scaling such learning directly in real-world computer systems is challenging and can introduce substantial security risks. We therefore propose Agent World Model in the Wild (WildAWM), a scalable pipeline for synthesizing controllable environments and tasks for training general computer-use agents (CUAs). Whereas existing approaches typically specialize in a single agent interaction interface, we construct executable environments that jointly support graphical user interfaces, ",pdfUrl:"https://arxiv.org/pdf/2610.26828",primaryCategory:"cs.AI",published:"2026-10-19T00:00:00Z"},{id:"2610.28698",title:"Scaling in Games: Continued Pre-Training For Embodied Agents In Diverse Virtual Worlds",up:52,href:"https://arxiv.org/abs/2610.28698",abstract:"Scaling data, diversity and model capacity has improved embodied learning in physical environments, where diverse experiences remain grounded in shared physical laws. Whether these gains extend to virtual worlds with different visual styles, dynamics, controls, and objectives remains unclear. We investigate this question through a controlled study of continued pre-training (CPT) across three axes: data volume, diversity, and model size. Our 120 training configurations span four model sizes from 0.8B to 27B, six data budgets from 50 to 1,600 hours, and five mixtures ranging from Minecraft-only ",pdfUrl:"https://arxiv.org/pdf/2610.28698",primaryCategory:"cs.AI",published:"2026-10-20T00:00:00Z"},{id:"2610.20538",title:"PrismaCoder: Pushing the Boundaries of Open Multimodal Code Intelligence through Decomposed Rubric Synthesis",up:50,href:"https://arxiv.org/abs/2610.20538",abstract:"Multimodal code intelligence connects the symbolic world of programs with the visual world their execution creates. Interest in this capability is burgeoning, as models are increasingly asked to produce charts, webpages, animations, and semi-structured documents. Recently, proprietary models have pushed far ahead, producing interactive artifacts even from a text description or a screenshot alone. Yet their data and training remain closed, and open progress is held back by the quantity and quality of available data and by the pipelines and methods for producing it. Quality is the harder of the ",pdfUrl:"https://arxiv.org/pdf/2610.20538",primaryCategory:"cs.CL",published:"2026-10-14T00:00:00Z"},{id:"2610.29722",title:"Retrieval Augmented Generation Compositionality",up:28,href:"https://arxiv.org/abs/2610.29722",abstract:"Retrieval Augmented Generation (RAG) grounds large language models in external knowledge. Modern pipelines combine embedding, chunking, retrieval, reranking, query augmentation, context compression, and agentic verification, yet these techniques are typically evaluated one at a time. It remains unclear whether their isolated gains survive composition, whether retrieval quality and answer faithfulness favor the same design choices, and whether conclusions from small corpora hold at large scale. We pre-declare three hypotheses and introduce LASAGNA, an open-source framework for controlled RAG ev",pdfUrl:"https://arxiv.org/pdf/2610.29722",primaryCategory:"cs.CL",published:"2026-10-21T00:00:00Z"},{id:"2610.28889",title:"Policy-Mask: Budget-Aware Adaptation of Diffusion Features to Discriminative Tasks",up:25,href:"https://arxiv.org/abs/2610.28889",abstract:"Selecting intermediate features from a frozen diffusion model for discriminative tasks is non-trivial because the useful signal is distributed across the denoising trajectory, network depth, and channels. In practice, this requires choosing a timestep, a block, and a channel subset. Existing methods either fix these choices by hand or optimize only a few extraction hyperparameters, most often the timestep, then reuse the same rule across inputs and budgets. We introduce Policy-Mask, a budget-conditioned policy trained on the downstream objective that jointly selects all three under a prescribe",pdfUrl:"https://arxiv.org/pdf/2610.28889",primaryCategory:"cs.CV",published:"2026-10-20T00:00:00Z"},{id:"2610.30113",title:"Quant-Arena: Benchmarking LLM Agents for Quantitative Trading Research",up:21,href:"https://arxiv.org/abs/2610.30113",abstract:"Quantitative research is an iterative loop: a researcher proposes a market hypothesis, implements it as an executable signal, tests it on historical data, and decides what to keep. Existing benchmarks score formulas, code, or individual trading decisions, leaving open whether large language models (LLMs) can complete this loop and produce strategies that work beyond the research period. We introduce Quant-Arena, a benchmark and public leaderboard for end-to-end quantitative research on real A-share market data. A model constructs features and stock-scoring code, receives feedback only on 2022-",pdfUrl:"https://arxiv.org/pdf/2610.30113",primaryCategory:"cs.CL",crossrefDoi:"https://doi.org/10.1145/3711896.3736570",year:2025,openalexId:"https://openalex.org/W4412877164",published:"2026-10-21T00:00:00Z",crossrefIssued:"2025-08-03"},{id:"2610.29545",title:"PACE: Periodic and Channel-Aligned Encoding of Four-Bit Recurrent States",up:19,href:"https://arxiv.org/abs/2610.29545",abstract:"Linear-attention language models keep their context in a recurrent state of fixed size, where an inference system stores one copy of this state for every sequence it decodes at the same time. Storing the state at lower precision therefore lets more sequences share an accelerator. Existing state quantizers round the state after every generated token and report that four bits lose accuracy unless the bit width is raised or the model is fine-tuned.\\par We introduce PACE, a post-hoc four-bit state quantizer. PACE rounds the state only once every few generated tokens, as chunked kernels already do ",pdfUrl:"https://arxiv.org/pdf/2610.29545",primaryCategory:"cs.CL",published:"2026-10-21T00:00:00Z"},{id:"2610.29680",title:"TraceForge: Distilling with Your Own Thinking",up:19,href:"https://arxiv.org/abs/2610.29680",abstract:"Using an LLM to generate training data for another is among the most general ways to train one, and it remains common practice. Some frontier teams have closed that route for their own models: what comes back is an answer, or a short summary, without the detailed reasoning trace behind it. That is a little ironic: they were themselves built on distilling human knowledge, and distilling an open-source model is still entirely routine; the restriction applies to their own outputs alone. Recent work recovers the hidden reasoning by replaying encrypted blocks across models. It somehow works, but it",pdfUrl:"https://arxiv.org/pdf/2610.29680",primaryCategory:"cs.AI",published:"2026-10-21T00:00:00Z"},{id:"2610.19376",title:"DeLoop: Repeated Actions as Self-Supervision for Long-Horizon Agents",up:18,href:"https://arxiv.org/abs/2610.19376",abstract:"Language-model agents that run long tasks often redo work they have already done: they re-issue a tool call they made earlier and get back exactly the same observation, a step that adds no new information. We identify this failure as a loop. Loops appear natively in Qwen, Llama, and Gemini agents and become far more common once the agent's history is compressed to fit its context window. To reduce these loops, we propose DeLoop, a self-supervised training method. DeLoop builds on a simple observation: the agent's own rollout can provide the supervision needed to learn from its loops. We use a ",pdfUrl:"https://arxiv.org/pdf/2610.19376",primaryCategory:"cs.AI",published:"2026-10-14T00:00:00Z"},{id:"2610.30108",title:"Multimodal Embodied Agents: A Unified Capability-centric Perspective from Computer-Use to Robot-Use",up:18,href:"https://arxiv.org/abs/2610.30108",abstract:"Multimodal agents (MMAs) sustain interaction through reasoning, memory, tools, and feedback, most visibly as computer-use agents, while robotic systems (RSs) couple sensing and actuation under physical dynamics. We define multimodal embodied agents (MMEAs) as goal-directed systems that couple multimodal task reasoning with physical action and revise decisions from the resulting feedback. This raises a central question: what changes when a multimodal agent moves from computer-use to robot-use? We introduce PAPAV, a unified capability-centric framework of five recurring functions: Perceive the c",pdfUrl:"https://arxiv.org/pdf/2610.30108",primaryCategory:"cs.RO",published:"2026-10-21T00:00:00Z"},{id:"2610.27598",title:"Meta Expert: Cross-Layer Expert Sharing for Storage- and Retrieval-Efficient MoE",up:17,href:"https://arxiv.org/abs/2610.27598",abstract:"As model parameters scale up, sparsely activated Mixture-of-Experts (MoE) approaches have become essential for model scaling. However, mainstream models currently adopt hierarchical architectures, where experts in different layers, although topologically independent, exhibit substantial similarity and redundancy in their stored content. Compared to the hierarchically arranged \\textbf{Local Expert} in existing mainstream models, we hypothesize that inter-layer shared \\textbf{Meta Expert} hold greater potential. To this end, we conduct a multi-dimensional empirical comparison between Local and M",pdfUrl:"https://arxiv.org/pdf/2610.27598",primaryCategory:"cs.AI",published:"2026-10-20T00:00:00Z"},{id:"2610.28887",title:"Building AI Research Teams for Autonomous Discovery of Linear Attention Architectures",up:16,href:"https://arxiv.org/abs/2610.28887",abstract:"Autonomous agents can increasingly propose ideas, modify code, and run experiments, creating an opportunity to accelerate scientific discovery using teams of collaborative AI researchers. To escape local minima in the discovery, we propose to encourage orthogonal exploration by constructing the team using agents with varying expertise. However, realizing this design requires more than diverse backgrounds. When experiments are costly, a team can test only a limited number of ideas, thereby creating the need to balance exploration and exploitation when selecting a subset of researchers to propos",pdfUrl:"https://arxiv.org/pdf/2610.28887",primaryCategory:"cs.CL",published:"2026-10-20T00:00:00Z"},{id:"2610.28416",title:"Code2Video-Compass: A Comprehensive Benchmark for General-Purpose Code-Based Video Generation across T2V, I2V, and V2V",up:14,href:"https://arxiv.org/abs/2610.28416",abstract:"Code-based video generation offers fine-grained control, targeted editing, and component reuse compared with direct video generation. This approach requires multimodal large language models (MLLMs) to translate visual and temporal requirements into executable programs that produce complete videos. However, existing code-based benchmarks primarily target specialized tasks, leaving complete video creation across diverse creative categories and input modalities insufficiently evaluated. We introduce Code2Video-Compass, a general-purpose benchmark for code-based video generation across text-to-vid",pdfUrl:"https://arxiv.org/pdf/2610.28416",primaryCategory:"cs.CV",published:"2026-10-20T00:00:00Z"},{id:"2610.28763",title:"Automating ML for Science: Can Frontier Agents Climb Scientific Hills in the Wild?",up:13,href:"https://arxiv.org/abs/2610.28763",abstract:"Frontier coding agents are increasingly framed as end-to-end automated researchers, and ML for science offers a demanding test of that promise: improving a scientific model often requires domain insight beyond routine ML engineering. We introduce Agent4Sci, a long-horizon testbed for measuring how far today's agents can improve the published best models on scientific ML benchmarks, spanning 20 benchmarks across 11 domains. Rather than ranking agents on a leaderboard, Agent4Sci asks what kinds of progress agents can make on these tasks under in-the-wild conditions, and where they fall short. Em",pdfUrl:"https://arxiv.org/pdf/2610.28763",primaryCategory:"cs.AI",published:"2026-10-20T00:00:00Z"},{id:"2610.13177",title:"CompactSplat: Spatially Adaptive Gaussian Distribution for Feedforward Scene Reconstruction",up:12,href:"https://arxiv.org/abs/2610.13177",abstract:"Reconstructing 3D scenes from sparse views without per-scene optimization remains highly challenging, especially for recovering accurate geometry and fine textures. While recent feedforward approaches leverage generalizable 3D Gaussian Splatting (3DGS) for scene generation, they typically assign one or multiple Gaussians to each pixel. Such uniform allocation not only produces highly redundant representations by wasting primitives in homogeneous areas, but also fails to exploit the inherent geometric priors of planar surfaces, often resulting in sub-optimal structural modeling. To address thes",pdfUrl:"https://arxiv.org/pdf/2610.13177",primaryCategory:"cs.CV",published:"2026-10-09T00:00:00Z"},{id:"2610.21204",title:"Entertain, then Cancel: How Thinking Makes Reasoning Models Read Some and Or Literally",up:12,href:"https://arxiv.org/abs/2610.21204",abstract:"When a speaker says ``some students passed'', listeners infer that not all of them did. Reasoning models now let users decide how long a model thinks before it answers, but we do not know what extra thinking does to such everyday inferences. We study this directly: we keep a model's weights fixed, change only how much it thinks, and record which reading it chooses. A second tool cuts the model's own reasoning at successive points and asks for an answer, showing where the reading changes. Thinking makes models read logical words as logic: it cancels the implicatures of \\emph{some} (\\emph{not al",pdfUrl:"https://arxiv.org/pdf/2610.21204",primaryCategory:"cs.AI",published:"2026-10-15T00:00:00Z"},{id:"2610.28711",title:"Qwen-Audio-3.1-ASR Technical Report",up:12,href:"https://arxiv.org/abs/2610.28711",abstract:"We present Qwen-Audio-3.1-ASR, a family of audio-language models that builds upon its predecesor Qwen-Audio-3.0-ASR with improved speech recognition and expanded capabilities in speaker-diarized transcription and general audio understanding. The family retains support for 30 languages and 16 Chinese dialects, together with instruction-controlled capabilities including historical-context conditioning, hierarchical hotword customization, and native transcription polishing. Speaker-diarized ASR produces structured outputs containing speaker labels, timestamps, and recognized text, maintaining con",pdfUrl:"https://arxiv.org/pdf/2610.28711",primaryCategory:"cs.SD",published:"2026-10-20T00:00:00Z"},{id:"2610.29317",title:"SpatialBrain: Spatial Intelligence Growing from Experience",up:12,href:"https://arxiv.org/abs/2610.29317",abstract:"Spatial reasoning requires more than access to geometric tools: a reasoner must decide when direct observation is sufficient and when to reconstruct, measure, or change reference frames. We present SpatialBrain, a framework that retains experience about these decisions while keeping its vision-language backbone fixed. The key distinction is between evidence about a scene and experience about how to reason with that evidence. 3DFusionMemory fuses current-scene observations into queryable spatial relations. A Spatial Skill Library provides reusable tool procedures, and Spatial Cognition associat",pdfUrl:"https://arxiv.org/pdf/2610.29317",primaryCategory:"cs.AI",published:"2026-10-21T00:00:00Z"},{id:"2610.30023",title:"RealMe: Immersive Volumetric Video from Minimal Captures",up:12,href:"https://arxiv.org/abs/2610.30023",abstract:"This paper addresses the problem of creating immersive volumetric videos from sparse and low-resolution capture resources. Conventional dense multi-view reconstruction methods can produce high-quality volumetric videos, but their reliance on costly capture setups makes them impractical in real-world scenarios. Recent approaches use generative models to relax capture requirements, but still suffer from limited resolution and 4D inconsistency. To overcome these constraints, we propose RealMe, a unified framework built around a high-resolution video diffusion model that enhances limited captures ",pdfUrl:"https://arxiv.org/pdf/2610.30023",primaryCategory:"cs.CV",published:"2026-10-21T00:00:00Z"},{id:"2610.30926",title:"Making MLLM Latents Matter: Factor-Aware Predictive Learning for Cinematic Video Generation",up:12,href:"https://arxiv.org/abs/2610.30926",abstract:"Cinematic video generation requires both temporal inference from limited inputs (i.e., sparse rather than frame-by-frame guidance) and factor-aware control of character, scene, action, and camera. Multimodal large language models (MLLMs) offer useful priors for both capabilities, but their representations are not automatically actionable for video generation: a Video Diffusion Transformer (DiT) may bypass them through native conditioning pathways, and using them does not ensure either factor-aware control or generation-compatible temporal prediction. We propose Factor-Aware Predictive Learning",pdfUrl:"https://arxiv.org/pdf/2610.30926",primaryCategory:"cs.CV",published:"2026-10-22T08:43:48Z"},{id:"2610.29560",title:"From VLM Planners to Robotic Agents: Self-Evolving Harnesses for History-Dependent Manipulation",up:11,href:"https://arxiv.org/abs/2610.29560",abstract:"Vision-language-action (VLA) models achieve strong performance across embodied manipulation tasks by unifying visual understanding, language conditioning, and action generation. However, long-horizon tasks can involve non-Markovian dependencies: successful decisions may require retaining task progress and past interaction outcomes, while partial observability and execution errors compound over time. Existing work has begun to address these challenges by augmenting foundation-model policies with memory and by introducing hierarchical architectures that separate high-level planning from low-leve",pdfUrl:"https://arxiv.org/pdf/2610.29560",primaryCategory:"cs.RO",published:"2026-10-21T00:00:00Z"},{id:"W4393160747",title:"ExpeL: LLM Agents Are Experiential Learners",up:0,href:"https://doi.org/10.1609/aaai.v38i17.29936",doi:"https://doi.org/10.1609/aaai.v38i17.29936",year:2024,openalexId:"https://openalex.org/W4393160747"},{id:"W4407759090",title:"A-Mem: Agentic Memory for LLM Agents",up:0,href:"https://doi.org/10.52202/085713-0593",doi:"https://doi.org/10.52202/085713-0593",year:2025,openalexId:"https://openalex.org/W4407759090"},{id:"W4391620956",title:"Understanding the planning of LLM agents: A survey",up:0,href:"https://doi.org/10.48550/arxiv.2402.02716",doi:"https://doi.org/10.48550/arxiv.2402.02716",year:2024,openalexId:"https://openalex.org/W4391620956"}]}}]);